def numTilePossibilities(tiles):
    def backtrack(counter):
        count = 0
        for tile in counter:
            if counter[tile] > 0:
                count += 1
                counter[tile] -= 1
                count += backtrack(counter)
                counter[tile] += 1
        return count

    counter = {tile: tiles.count(tile) for tile in set(tiles)}
    return backtrack(counter)

